stateHomeAnchor:
base::FilePath StateHome() {
  auto env = base::Environment::Create();
  if (auto value = env->GetVar("AUX_HOME"); value && !value->empty())
    return base::FilePath(*value);
  base::FilePath home;
  return base::PathService::Get(base::DIR_HOME, &home)
             ? home.AppendASCII(".aux")
             : base::FilePath();
}

proposedStateHomePrefix:
auto selected = aux::peer::ReadNativeSelectedStateHome();
if (selected.route != aux::peer::SelectedStateHomeRoute::unselected)
  return selected.route == aux::peer::SelectedStateHomeRoute::current ? selected.path : base::FilePath();
